Simulation with Poisson order arrivals, log-normal order sizes, and geometric price
placement relative to the best quote. The matching engine runs price-time priority
continuously.

rng  = np.random.default_rng(42)
lob  = LimitOrderBook(tick_size=0.5)
P0, tick = 100.0, 0.5

for i in range(10):
    lob.bids[round(P0 - (i + 0.5) * tick, 8)] = max(1, int(rng.lognormal(2.2, 0.7)))
    lob.asks[round(P0 + (i + 0.5) * tick, 8)] = max(1, int(rng.lognormal(2.2, 0.7)))
lob._refresh()

snapshots_prob = []

for t in range(3000):
    if lob.best_bid is None or lob.best_ask is None:
        break
    for _ in range(int(rng.poisson(2))):
        if lob.best_bid is None or lob.best_ask is None:
            break
        side = 'buy' if rng.random() < 0.5 else 'sell'
        sz   = max(1, int(rng.lognormal(2.2, 0.7)))
        if rng.random() < 0.25:
            opp = sum(lob.asks.values()) if side == 'buy' else sum(lob.bids.values())
            lob.add_market(side, min(sz, max(1, int(opp * 0.4))))
        else:
            n_ticks = min(int(rng.geometric(0.45)) - 1, 20)
            price = (lob.best_bid - n_ticks * tick) if side == 'buy' \
                    else (lob.best_ask + n_ticks * tick)
            lob.add_limit(side, price, sz)
    if t % 8 == 7:
        if len(lob.bids) > 20:
            lob.cancel('buy', min(lob.bids))
        if len(lob.asks) > 20:
            lob.cancel('sell', max(lob.asks))
    if t % 15 == 0 and lob.mid_price is not None:
        bids, asks = lob.snapshot(12)
        snapshots_prob.append({'t': t, 'bids': bids, 'asks': asks, 'mid': lob.mid_price})

plot_lob_dynamics(
    snapshots_prob,
    title='Probabilistic Generative Model – LOB Dynamics\n'
          '(Poisson arrivals, log-normal sizes, geometric price placement)'
)
print(f'{len(snapshots_prob)} snapshots, '
      f'mid-price: {snapshots_prob[0]["mid"]:.2f} → {snapshots_prob[-1]["mid"]:.2f}')

Black–Scholes–Merton pricing and Greeks, plus DV01 vector construction for coupon bonds.

# ── BSM ──────────────────────────────────────────────────────────────
def bsm_price(S, K, T, sigma, r=0.0, cp=1):
    d1 = (np.log(S/K) + (r + 0.5*sigma**2)*T) / (sigma * np.sqrt(T))
    d2 = d1 - sigma * np.sqrt(T)
    if cp == 1:
        return S * norm.cdf(d1) - K * np.exp(-r*T) * norm.cdf(d2)
    return K * np.exp(-r*T) * norm.cdf(-d2) - S * norm.cdf(-d1)

def bsm_delta(S, K, T, sigma, r=0.0, cp=1):
    if T <= 0:
        return float(cp == 1 and S > K)
    d1 = (np.log(S/K) + (r + 0.5*sigma**2)*T) / (sigma * np.sqrt(T))
    return norm.cdf(d1) if cp == 1 else norm.cdf(d1) - 1

def bsm_gamma(S, K, T, sigma, r=0.0):
    if T <= 0:
        return 0.0
    d1 = (np.log(S/K) + (r + 0.5*sigma**2)*T) / (sigma * np.sqrt(T))
    return norm.pdf(d1) / (S * sigma * np.sqrt(T))

# ── Yield curve setup ─────────────────────────────────────────────────
D = 20                              # number of maturity buckets
maturities = np.linspace(0.5, 10, D)

def pc_level(t):  return np.ones_like(t)
def pc_slope(t):  return (t - t.mean()) / (t.max() - t.min())
def pc_curve(t):
    s = pc_slope(t)
    return s**2 - (s**2).mean()

def dv01_bond(maturity, coupon=0.05, notional=1e6):
    """Dollar DV01 vector across maturity grid (dollar per unit yield change)."""
    cash_times = np.arange(0.5, maturity + 0.01, 0.5)
    r = 0.04
    d = np.zeros(D)
    for t_cf in cash_times:
        cf = coupon * 0.5 * notional if t_cf < maturity else (coupon * 0.5 + 1) * notional
        pv = cf * np.exp(-r * t_cf)
        idx_m = np.argmin(np.abs(maturities - t_cf))
        d[idx_m] += pv * t_cf
    return d

# ── CVaR ──────────────────────────────────────────────────────────────
def cvar95(x):
    q = np.percentile(x, 5)
    return -np.mean(x[x <= q])
